example.request:
POST /api/workspaces
Content-Type: application/json
Authorization: Bearer {token}

{
  "name": "My Startup",
  "onboarding": {
    "goal": {
      "primaryGoal": "grow_audience"
    },
    "audience": {
      "audienceType": "founders"
    },
    "voice": {
      "tones": ["casual", "friendly"]
    },
    "contentStrategy": {
      "pillars": ["education", "storytelling"]
    },
    "constraints": {
      "platforms": ["threads", "linkedin"]
    }
  }
}

POST /api/ai/content
Content-Type: application/json
Authorization: Bearer {token}

{
  "workspaceId": "workspace-uuid",
  "tone": "casual",
  "language": "en",
  "includeHashtags": true,
  "selectedAccounts": [
    { "id": "account-uuid", "platform": "threads" }
  ]
}

POST /api/workspaces/{workspaceId}/tags
Content-Type: application/json
Authorization: Bearer {token}

{
  "name": "productivity tips",
  "category": "topic"
}
